  'dash.settings.autonomous_confirm': 'التحول إلى الوضع المستقل؟\n\nهذا يوافق تلقائياً على كل فئة أدوات — bash، git، file_write، file_edit، database_query، browser، http_request — بما في ذلك مجموعتها المدمرة (rm، format، deletes، overwrites). العمليات الوحيدة التي لا تزال تطلب تأكيداً هي الأنماط غير القابلة للعكس (force-push، hard reset، history rewrites، package publish، git_commit --amend) — تلك لن تتخرج أبداً.\n\nاختر هذا فقط إذا كنت تريد تشغيل Ava دون تأكيدات عبر جلسات طويلة، وعلى مساحة عمل يمكنك التعافي منها من كتابة خاطئة عبر git.',
