  'dash.settings.custom_model_desc': 'وجه Ava نحو أي نموذج — محلي (Ollama، LM Studio، vLLM على جهازك) أو عن بُعد (عقدة vLLM خاصة، ضبط دقيق مستضاف ذاتياً، OpenRouter، Together، أي شيء يتحدث واجهة OpenAI Chat Completions API). الخوادم المحلية تبقى على جهازك؛ نقاط النهاية البعيدة تحصل على أي أمان تعرضه نقطة النهاية الخاصة بها. أعد تشغيل لوحة الدردشة بعد الحفظ لتفعيل التغييرات.',
